const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');
const { updateCustomer } = require('/home/node/scripts/cvpro-helpers.js');
const { fileBuffer, mimeType, fileType, customerId } = $input.first().json.body;
const buf = Buffer.isBuffer(fileBuffer) ? fileBuffer : Buffer.from(fileBuffer.data || fileBuffer);
const base64 = buf.toString('base64');
const prompts = {
  cv: 'Extract all text from this CV/resume. Return only the text.',
  linkedin: 'Extract text from this LinkedIn screenshot.',
  voice: 'Transcribe this voice note accurately.',
};
const prompt = prompts[fileType] || 'Extract all readable text from this file.';
const res = await $http.request({
  method: 'POST',
  url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${process.env.GEMINI_API_KEYS.split(',')[0]}`,
  headers: { 'Content-Type': 'application/json' },
  body: {
    contents: [{ parts: [{ text: prompt }, { inlineData: { mimeType, data: base64 } }] }],
    generationConfig: { temperature: 0.2 },
  },
});
const extractedText = res.candidates?.[0]?.content?.parts?.[0]?.text || '';
if (customerId) {
  await updateCustomer($http, customerId, { meta: { last_processed_file: extractedText.substring(0, 500) } });
}
return [{ json: { extractedText, customerId } }];
